from solution import multiply
import pytest
from hypothesis import given
import hypothesis.strategies as st


def ref_unit(n: int) -> int:
    return abs(n) % 10


def ref_multiply(a: int, b: int) -> int:
    return ref_unit(a) * ref_unit(b)


# --- explicit spec examples ---
def test_examples_from_spec():
    assert multiply(148, 412) == 16
    assert multiply(19, 28) == 72
    assert multiply(2020, 1851) == 0
    assert multiply(14, -15) == 20


def test_single_digits_are_plain_product():
    assert multiply(3, 7) == 21
    assert multiply(0, 9) == 0
    assert multiply(5, 5) == 25
    assert multiply(9, 9) == 81


def test_negative_single_digit_uses_abs():
    # unit digit of -4 is 4, of -5 is 5
    assert multiply(-4, 3) == 12
    assert multiply(4, -3) == 12
    assert multiply(-4, -3) == 12
    assert multiply(-14, -24) == 16  # 4*4, distinguishes abs()%10 from python %10


def test_python_modulo_trap_for_negatives():
    # Naive `a % 10` in Python gives 6 for -14, but spec unit digit is 4.
    # 6*6=36 vs correct 4*4=16
    assert multiply(-14, -14) == 16
    assert multiply(-14, 22) == 8
    assert multiply(-11, -19) == 9


def test_result_distinguishes_unit_product_from_product_unit():
    # (19*28) % 10 == 2, but unit-product is 9*8 == 72
    assert multiply(19, 28) == 72
    assert multiply(19, 28) != (19 * 28) % 10
    assert multiply(148, 412) == 16
    assert multiply(99, 99) == 81


# --- properties ---

@given(st.integers(-100000, 100000), st.integers(-100000, 100000))
def test_equivalence_to_reference_model(a, b):
    assert multiply(a, b) == ref_unit(a) * ref_unit(b)


@given(st.integers(-100000, 100000), st.integers(-100000, 100000))
def test_result_range_bounded_0_to_81(a, b):
    r = multiply(a, b)
    assert isinstance(r, int)
    assert 0 <= r <= 81


@given(st.integers(-100000, 100000), st.integers(-100000, 100000))
def test_commutativity(a, b):
    assert multiply(a, b) == multiply(b, a)


@given(st.integers(-100000, 100000), st.integers(-100000, 100000))
def test_sign_invariance(a, b):
    assert multiply(a, b) == multiply(-a, b) == multiply(a, -b) == multiply(-a, -b)
    assert multiply(a, b) == multiply(abs(a), abs(b))


@given(st.integers(-100000, 100000), st.integers(-100000, 100000),
       st.integers(-1000, 1000), st.integers(-1000, 1000))
def test_periodicity_adding_multiples_of_ten(a, b, k1, k2):
    assert multiply(a + 10 * k1, b + 10 * k2) == multiply(a, b)


@given(st.integers(-100000, 100000), st.integers(-100000, 100000))
def test_depends_only_on_unit_digits(a, b):
    assert multiply(a, b) == multiply(ref_unit(a), ref_unit(b))


@given(st.integers(-100000, 100000), st.integers(0, 9))
def test_zero_unit_digit_forces_zero(a, d):
    # construct b with unit digit 0
    b = d * 10 if a >= 0 else -d * 10
    # ensure unit digit really 0 (d*10 always ends in 0)
    assert ref_unit(b) == 0
    assert multiply(a, b) == 0
    assert multiply(b, a) == 0


@given(st.integers(0, 9), st.integers(0, 9))
def test_exhaustive_single_digit_table(x, y):
    assert multiply(x, y) == x * y


@given(st.integers(-100000, 100000))
def test_multiply_by_zero_integer_is_zero(a):
    # 0 has unit digit 0
    assert multiply(a, 0) == 0
    assert multiply(0, a) == 0
